using System.ComponentModel;
using System.Net;
using System.Text.Json;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;

var builder = Host.CreateApplicationBuilder(args);
builder.Configuration.AddEnvironmentVariables();

var apiKey = builder.Configuration["AI:ApiKey"]
    ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the AI:ApiKey configuration value or OPENAI_API_KEY environment variable.");

var modelId = builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18";

builder.Services.AddHttpClient("WebSearch");
builder.Services.AddSingleton<Notebook>();
builder.Services.AddChatClient(cb => cb
    .UseOpenAIChatClient(modelId, new OpenAI.OpenAIClient(apiKey)));
builder.Services.AddLogging(lb => lb.SetMinimumLevel(LogLevel.Warning));

using var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();
var httpFactory = host.Services.GetRequiredService<IHttpClientFactory>();
var notebook = host.Services.GetRequiredService<Notebook>();
var loggerFactory = host.Services.GetRequiredService<ILoggerFactory>();

// Define tools the agent can use
var tools = new List<AITool>
{
    AIFunctionFactory.Create(
        (string query) => WebSearchAsync(httpFactory, query),
        "web_search",
        "Searches the web for the given query and returns relevant result snippets. Use this to find information about a topic."),

    AIFunctionFactory.Create(
        ([Description("A short title for this note")] string title,
         [Description("The content to save")] string content) =>
        {
            notebook.Add(title, content);
            return $"Note saved: \"{title}\"";
        },
        "save_note",
        "Saves a research note with a title and content. Use this to record key findings during research."),

    AIFunctionFactory.Create(
        () => notebook.GetAll(),
        "get_notes",
        "Retrieves all saved research notes. Use this to review what has been collected so far."),
};

var agent = new ChatClientAgent(
    chatClient,
    instructions: """
        You are a research agent. When given a topic, you:
        1. Search the web multiple times with different queries to gather diverse information.
        2. Save important findings as notes using the save_note tool.
        3. After gathering enough information (at least 3 searches), retrieve your notes and
           produce a well-structured summary with key findings and sources.
        Be thorough but concise. Always cite where information came from.
        """,
    name: "ResearchAgent",
    description: "An AI agent that researches topics by searching the web and summarizing findings.",
    tools: tools,
    loggerFactory: loggerFactory);

Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║        Research Agent (MAF)          ║");
Console.WriteLine("╚══════════════════════════════════════╝");
Console.WriteLine("Enter a research topic (or 'quit' to exit):\n");

while (true)
{
    Console.ForegroundColor = ConsoleColor.Cyan;
    Console.Write("> ");
    Console.ResetColor();

    var topic = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    notebook.Clear();

    Console.ForegroundColor = ConsoleColor.DarkGray;
    Console.WriteLine($"\nResearching: {topic}...\n");
    Console.ResetColor();

    try
    {
        var runOptions = new ChatClientAgentRunOptions(
            new ChatOptions { Temperature = 0f, MaxOutputTokens = 4096 });

        await foreach (var update in agent.RunStreamingAsync(
            $"Research the following topic thoroughly: {topic}",
            runOptions: runOptions))
        {
            if (!string.IsNullOrEmpty(update.Text))
            {
                Console.Write(update.Text);
            }
        }

        Console.WriteLine("\n");
    }
    catch (Exception ex)
    {
        Console.ForegroundColor = ConsoleColor.Red;
        Console.WriteLine($"Error: {ex.Message}");
        Console.ResetColor();
    }
}

Console.WriteLine("Goodbye!");
return;

// --- Web search tool implementation ---
static async Task<string> WebSearchAsync(IHttpClientFactory httpFactory, string query)
{
    Console.ForegroundColor = ConsoleColor.Yellow;
    Console.WriteLine($"  🔍 Searching: \"{query}\"");
    Console.ResetColor();

    try
    {
        using var client = httpFactory.CreateClient("WebSearch");
        client.Timeout = TimeSpan.FromSeconds(10);
        client.DefaultRequestHeaders.UserAgent.ParseAdd(
            "Mozilla/5.0 (compatible; ResearchAgent/1.0)");

        var encoded = WebUtility.UrlEncode(query);
        var url = $"https://lite.duckduckgo.com/lite/?q={encoded}";
        var html = await client.GetStringAsync(url);

        // Extract text snippets from the lite HTML response
        var snippets = ExtractSnippets(html, maxSnippets: 5);

        return snippets.Count > 0
            ? $"Search results for \"{query}\":\n" + string.Join("\n\n", snippets)
            : $"No results found for \"{query}\". Try a different search query.";
    }
    catch (Exception ex)
    {
        return $"Search failed for \"{query}\": {ex.Message}. Try a different query.";
    }
}

static List<string> ExtractSnippets(string html, int maxSnippets)
{
    var snippets = new List<string>();

    // Extract text from snippet class elements and result links
    var spanStart = 0;
    while (snippets.Count < maxSnippets)
    {
        // Look for snippet content between <td> tags with class "result-snippet"
        var snippetIdx = html.IndexOf("result-snippet", spanStart, StringComparison.Ordinal);
        if (snippetIdx < 0)
            break;

        var tdClose = html.IndexOf('>', snippetIdx);
        if (tdClose < 0) break;

        var tdEnd = html.IndexOf("</td>", tdClose, StringComparison.OrdinalIgnoreCase);
        if (tdEnd < 0) break;

        var text = StripHtml(html[(tdClose + 1)..tdEnd]).Trim();
        if (text.Length > 30)
        {
            snippets.Add($"- {text}");
        }

        spanStart = tdEnd + 5;
    }

    // Fallback: extract from result links if no snippets found
    if (snippets.Count == 0)
    {
        spanStart = 0;
        while (snippets.Count < maxSnippets)
        {
            var linkIdx = html.IndexOf("result-link", spanStart, StringComparison.Ordinal);
            if (linkIdx < 0) break;

            var aClose = html.IndexOf('>', linkIdx);
            if (aClose < 0) break;

            var aEnd = html.IndexOf("</a>", aClose, StringComparison.OrdinalIgnoreCase);
            if (aEnd < 0) break;

            var linkText = StripHtml(html[(aClose + 1)..aEnd]).Trim();
            if (linkText.Length > 10)
            {
                snippets.Add($"- {linkText}");
            }

            spanStart = aEnd + 4;
        }
    }

    return snippets;
}

static string StripHtml(string html)
{
    var result = System.Text.RegularExpressions.Regex.Replace(html, "<[^>]+>", " ");
    result = WebUtility.HtmlDecode(result);
    return System.Text.RegularExpressions.Regex.Replace(result, @"\s+", " ");
}

// --- Notebook for storing research notes ---
public sealed class Notebook
{
    private readonly List<(string Title, string Content, DateTime Timestamp)> _notes = [];

    public void Add(string title, string content)
    {
        _notes.Add((title, content, DateTime.UtcNow));
        Console.ForegroundColor = ConsoleColor.Green;
        Console.WriteLine($"  📝 Note saved: \"{title}\"");
        Console.ResetColor();
    }

    public string GetAll()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        return string.Join("\n\n", _notes.Select((n, i) =>
            $"[Note {i + 1}] {n.Title}\n{n.Content}"));
    }

    public void Clear() => _notes.Clear();
}

