// --- Web search tool implementation ---
static async Task<string> WebSearchAsync(IHttpClientFactory httpFactory, string query)
{
    Console.ForegroundColor = ConsoleColor.Yellow;
    Console.WriteLine($"  🔍 Searching: \"{query}\"");
    Console.ResetColor();

    try
    {
        using var client = httpFactory.CreateClient("WebSearch");
        client.Timeout = TimeSpan.FromSeconds(10);
        client.DefaultRequestHeaders.UserAgent.ParseAdd(
            "Mozilla/5.0 (compatible; ResearchAgent/1.0)");

        var encoded = WebUtility.UrlEncode(query);
        var url = $"https://lite.duckduckgo.com/lite/?q={encoded}";
        var html = await client.GetStringAsync(url);

        // Extract text snippets from the lite HTML response
        var snippets = ExtractSnippets(html, maxSnippets: 5);

        return snippets.Count > 0
            ? $"Search results for \"{query}\":\n" + string.Join("\n\n", snippets)
            : $"No results found for \"{query}\". Try a different search query.";
    }
    catch (Exception ex)
    {
        return $"Search failed for \"{query}\": {ex.Message}. Try a different query.";
    }
}

static List<string> ExtractSnippets(string html, int maxSnippets)
{
    var snippets = new List<string>();

    // Extract text from snippet class elements and result links
    var spanStart = 0;
    while (snippets.Count < maxSnippets)
    {
        // Look for snippet content between <td> tags with class "result-snippet"
        var snippetIdx = html.IndexOf("result-snippet", spanStart, StringComparison.Ordinal);
        if (snippetIdx < 0)
            break;

        var tdClose = html.IndexOf('>', snippetIdx);
        if (tdClose < 0) break;

        var tdEnd = html.IndexOf("</td>", tdClose, StringComparison.OrdinalIgnoreCase);
        if (tdEnd < 0) break;

        var text = StripHtml(html[(tdClose + 1)..tdEnd]).Trim();
        if (text.Length > 30)
        {
            snippets.Add($"- {text}");
        }

        spanStart = tdEnd + 5;
    }

    // Fallback: extract from result links if no snippets found
    if (snippets.Count == 0)
    {
        spanStart = 0;
        while (snippets.Count < maxSnippets)
        {
            var linkIdx = html.IndexOf("result-link", spanStart, StringComparison.Ordinal);
            if (linkIdx < 0) break;

            var aClose = html.IndexOf('>', linkIdx);
            if (aClose < 0) break;

            var aEnd = html.IndexOf("</a>", aClose, StringComparison.OrdinalIgnoreCase);
            if (aEnd < 0) break;

            var linkText = StripHtml(html[(aClose + 1)..aEnd]).Trim();
            if (linkText.Length > 10)
            {
                snippets.Add($"- {linkText}");
            }

            spanStart = aEnd + 4;
        }
    }

    return snippets;
}

static string StripHtml(string html)
{
    var result = System.Text.RegularExpressions.Regex.Replace(html, "<[^>]+>", " ");
    result = WebUtility.HtmlDecode(result);
    return System.Text.RegularExpressions.Regex.Replace(result, @"\s+", " ");
}

// --- Notebook for storing research notes ---
public sealed class Notebook
{
    private readonly List<(string Title, string Content, DateTime Timestamp)> _notes = [];

    public void Add(string title, string content)
    {
        _notes.Add((title, content, DateTime.UtcNow));
        Console.ForegroundColor = ConsoleColor.Green;
        Console.WriteLine($"  📝 Note saved: \"{title}\"");
        Console.ResetColor();
    }

    public string GetAll()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        return string.Join("\n\n", _notes.Select((n, i) =>
            $"[Note {i + 1}] {n.Title}\n{n.Content}"));
    }

    public void Clear() => _notes.Clear();
}

