121. // --- Web search tool implementation ---
122. static async Task<string> WebSearchAsync(IHttpClientFactory httpFactory, string query)
123. {
124.     Console.ForegroundColor = ConsoleColor.Yellow;
125.     Console.WriteLine($"  🔍 Searching: \"{query}\"");
126.     Console.ResetColor();
127. 
128.     try
129.     {
130.         using var client = httpFactory.CreateClient("WebSearch");
131.         client.Timeout = TimeSpan.FromSeconds(10);
132.         client.DefaultRequestHeaders.UserAgent.ParseAdd(
133.             "Mozilla/5.0 (compatible; ResearchAgent/1.0)");
134. 
135.         var encoded = WebUtility.UrlEncode(query);
136.         var url = $"https://lite.duckduckgo.com/lite/?q={encoded}";
137.         var html = await client.GetStringAsync(url);
138. 
139.         // Extract text snippets from the lite HTML response
140.         var snippets = ExtractSnippets(html, maxSnippets: 5);
141. 
142.         return snippets.Count > 0
143.             ? $"Search results for \"{query}\":\n" + string.Join("\n\n", snippets)
144.             : $"No results found for \"{query}\". Try a different search query.";
145.     }
146.     catch (Exception ex)
147.     {
148.         return $"Search failed for \"{query}\": {ex.Message}. Try a different query.";
149.     }
150. }
151. 
152. static List<string> ExtractSnippets(string html, int maxSnippets)
153. {
154.     var snippets = new List<string>();
155. 
156.     // Extract text from snippet class elements and result links
157.     var spanStart = 0;
158.     while (snippets.Count < maxSnippets)
159.     {
160.         // Look for snippet content between <td> tags with class "result-snippet"
161.         var snippetIdx = html.IndexOf("result-snippet", spanStart, StringComparison.Ordinal);
162.         if (snippetIdx < 0)
163.             break;
164. 
165.         var tdClose = html.IndexOf('>', snippetIdx);
166.         if (tdClose < 0) break;
167. 
168.         var tdEnd = html.IndexOf("</td>", tdClose, StringComparison.OrdinalIgnoreCase);
169.         if (tdEnd < 0) break;
170. 
171.         var text = StripHtml(html[(tdClose + 1)..tdEnd]).Trim();
172.         if (text.Length > 30)
173.         {
174.             snippets.Add($"- {text}");
175.         }
176. 
177.         spanStart = tdEnd + 5;
178.     }
179. 
180.     // Fallback: extract from result links if no snippets found
181.     if (snippets.Count == 0)
182.     {
183.         spanStart = 0;
184.         while (snippets.Count < maxSnippets)
185.         {
186.             var linkIdx = html.IndexOf("result-link", spanStart, StringComparison.Ordinal);
187.             if (linkIdx < 0) break;
188. 
189.             var aClose = html.IndexOf('>', linkIdx);
190.             if (aClose < 0) break;
191. 
192.             var aEnd = html.IndexOf("</a>", aClose, StringComparison.OrdinalIgnoreCase);
193.             if (aEnd < 0) break;
194. 
195.             var linkText = StripHtml(html[(aClose + 1)..aEnd]).Trim();
196.             if (linkText.Length > 10)
197.             {
198.                 snippets.Add($"- {linkText}");
199.             }
200. 
201.             spanStart = aEnd + 4;
202.         }
203.     }
204. 
205.     return snippets;
206. }
207. 
208. static string StripHtml(string html)
209. {
210.     var result = System.Text.RegularExpressions.Regex.Replace(html, "<[^>]+>", " ");
211.     result = WebUtility.HtmlDecode(result);
212.     return System.Text.RegularExpressions.Regex.Replace(result, @"\s+", " ");
213. }
