216. public sealed class Notebook
217. {
218.     private readonly List<(string Title, string Content, DateTime Timestamp)> _notes = [];
219. 
220.     public void Add(string title, string content)
221.     {
222.         _notes.Add((title, content, DateTime.UtcNow));
223.         Console.ForegroundColor = ConsoleColor.Green;
224.         Console.WriteLine($"  📝 Note saved: \"{title}\"");
225.         Console.ResetColor();
226.     }
227. 
228.     public string GetAll()
229.     {
230.         if (_notes.Count == 0)
231.             return "No notes saved yet.";
232. 
233.         return string.Join("\n\n", _notes.Select((n, i) =>
234.             $"[Note {i + 1}] {n.Title}\n{n.Content}"));
235.     }
236. 
237.     public void Clear() => _notes.Clear();
238. }
